function cms_care_ui(string $key, string $locale = ''): string
{
    $locale = $locale === '' ? cms_care_locale() : cms_locale($locale);
    $row = cms_care_phrases()[$key] ?? null;
    if (!is_array($row)) {
        return $key;
    }
    $text = trim((string) ($row[$locale] ?? ''));
    return $text !== '' ? $text : (string) ($row['fa'] ?? $key);
}

