{
    $map = [
        'نشست نامعتبر است. صفحه را تازه کنید.' => 'err-csrf',
        'این ورود فقط وقت‌ها و آماده شدن را نشان می‌دهد.' => 'err-companion',
        'اول وارد پرونده شوید.' => 'err-login',
        'اول با رمز خود پرونده وارد شوید.' => 'err-own',
        'تعویض رمز از این صفحه بسته است. از مطب بخواهید.' => 'err-rotate-off',
        'تعویض رمز چند بار پشت سر هم ممکن نیست. کمی بعد دوباره بزنید.' => 'err-rotate-limit',
        'با این شماره و کد، پرونده‌ای باز نشد.' => 'err-open',
        'رمز همراه از این صفحه بسته است.' => 'err-mate-off',
        'ساخت رمز همراه چند بار پشت سر هم ممکن نیست. کمی بعد دوباره بزنید.' => 'err-mate-limit',
        'برای این شماره چهار همراه ثبت شده. یکی را ببندید.' => 'err-mate-full',
        'فقط عکس خودتان را می‌توانید بردارید.' => 'err-photo-own',
        'فقط نظر خودتان را می‌توانید بردارید.' => 'err-comment-own',
        'فرستادن پیام از این صفحه موقتاً بسته است.' => 'err-message-off',
        'بدون تأیید، متن و عکس ذخیره نمی‌شود.' => 'err-consent',
        'بدون تأیید، برگه پزشکی ذخیره نمی‌شود.' => 'err-sheet',
        'این درخواست چند بار پشت سر هم ممکن نیست. کمی بعد دوباره بزنید.' => 'err-sms-limit',
        'این بخش بسته است.' => 'err-closed',
        'حجم عکس از حد مجاز سرور بیشتر است.' => 'err-photo',
        'این دارو را فقط مطب می‌تواند متوقف کند.' => 'err-med-clinic',
        'این کار پیدا نشد.' => 'err-need',
        'فقط کار خودتان را می‌توانید بردارید.' => 'err-need-own',
        'این یادآوری پیدا نشد.' => 'err-remind',
        'این درخواست پیدا نشد.' => 'err-ask',
    ];
    $key = $map[$text] ?? '';
    return $key !== '' ? cms_care_ui($key) : $text;
}

function cms_care_builtin(string $key, string $locale): string
{
    $locale = cms_locale($locale);
    $pack = [
        'care_title' => ['en' => 'Care chart', 'ar' => 'ملف الرعاية', 'zh' => '治疗档案'],
        'care_notice' => ['en' => 'This page is not an examination and does not make a treatment plan. The clinic sees the photo and note at the desk and answers there. In an emergency, call the number on this page.', 'ar' => 'هذه الصفحة ليست فحصاً ولا تضع خطة علاج. العيادة ترى الصورة والملاحظة في المكتب وترد من هناك. في الطوارئ اتصل بالرقم في هذه الصفحة.', 'zh' => '这一页不是诊疗，也不会制定治疗计划。诊室在工作台看到照片和说明并在那里回复。紧急情况请拨打本页上的号码。'],
        'care_consent' => ['en' => 'I know the clinic sees this note and photo, and it is not published on the public site.', 'ar' => 'أعرف أن العيادة ترى هذا النص والصورة، وأنهما لا يُنشران في الموقع العام.', 'zh' => '我知道诊室会看到这段文字和照片，并且不会发到公开网站。'],
        'care_h_next' => ['en' => 'Next visit', 'ar' => 'الموعد التالي', 'zh' => '下次就诊'],
        'care_h_stage' => ['en' => 'Course of care', 'ar' => 'مسار الرعاية', 'zh' => '治疗过程'],
        'care_h_need' => ['en' => 'What is needed', 'ar' => 'ما المطلوب', 'zh' => '需要做的事'],
        'care_h_med' => ['en' => 'Medicines', 'ar' => 'الأدوية', 'zh' => '药物'],
        'care_h_remind' => ['en' => 'Personal reminder', 'ar' => 'تذكير شخصي', 'zh' => '个人提醒'],
        'care_h_talk' => ['en' => 'Message the clinic', 'ar' => 'مراسلة العيادة', 'zh' => '给诊室留言'],
        'care_label_problem' => ['en' => 'Current problem', 'ar' => 'المشكلة الحالية', 'zh' => '目前的问题'],
        'care_label_medicines' => ['en' => 'Current medicines', 'ar' => 'الأدوية الحالية', 'zh' => '目前的药物'],
        'care_label_allergy' => ['en' => 'Allergy', 'ar' => 'الحساسية', 'zh' => '过敏'],
        'care_label_extra' => ['en' => 'Other note', 'ar' => 'ملاحظة أخرى', 'zh' => '其他说明'],
    ];
    return (string) ($pack[$key][$locale] ?? '');
}
